@test
def test_numbers():
    assert closec(sp.bernoulli(8), [1.0, -0.5, 0.16666666666666666, 0.0, -0.033333333333275914, 0.0, 0.02380952380952236, 0.0, -0.03333333333333301], 1e-09)
    assert closec(sp.euler(8), [1.0, 0.0, -1.0, 0.0, 5.000000000000001, 0.0, -61.00000000000001, 0.0, 1385.0000000000002], 1e-09)
    assert closec(sp.bernoulli(1), [1.0, -0.5], 1e-09)
    assert closec(sp.euler(0), [1.0], 1e-09)
    assert sp.stirling2(10, 4, exact=True) == 34105
    assert closec(sp.stirling2(np.array([6, 8]), np.array([3, 4])), [90.0, 1701.0], 1e-09)
    assert sp.factorial2(9, exact=True) == 945
    assert sp.factorialk(10, 3, exact=True) == 280
    assert closec(sp.factorial2(np.array([5, 6])), [15.000000000000005, 48.0], 1e-09)
    assert closec(sp.factorialk(np.array([10, 7]), 3), [280.00000000000045, 28.00000000000002], 1e-09)
test_numbers()
